<?php
require_once __DIR__.'/portal.php';
function rmmc_staff_events(string $role): void {
    rmmc_require_roles($role);
    $status=trim((string)($_GET['status']??''));
    $allowed=['Upcoming','Ongoing','Finished','Cancelled'];
    if ($status!=='' && !in_array($status,$allowed,true)) $status='';
    $rows=$status!=='' ? rmmc_all('SELECT * FROM events WHERE status=? ORDER BY event_date DESC','s',[$status]) : rmmc_all('SELECT * FROM events ORDER BY event_date DESC LIMIT 100');
    $editId=(int)($_GET['edit']??0);
    $edit=$editId ? rmmc_one('SELECT * FROM events WHERE id=?','i',[$editId]) : null;
    $event=$edit??[];
    rmmc_shell_start('Events',$role);
    ?><div class="welcome"><h1>Manage events</h1><p>Create, edit, and manage ITE and COMSOC events. Attendance history is preserved when an event is cancelled.</p></div>
    <section class="panel"><h2><?=$edit?'Edit event':'Create event'?></h2><form action="event_action.php" method="post"><input type="hidden" name="csrf" value="<?=rmmc_e(rmmc_csrf())?>"><input type="hidden" name="action" value="save"><input type="hidden" name="id" value="<?=(int)($event['id']??0)?>"><div class="form-grid">
    <?php $fields=[['title','Title','text'],['event_date','Event date','date'],['time_start','Start time','time'],['time_end','End time','time'],['location','Venue','text'],['school_year','Academic year','text'],['semester','Semester','text'],['morning_in','Morning Time In','time'],['morning_out','Morning Time Out','time'],['afternoon_in','Afternoon Time In','time'],['afternoon_out','Afternoon Time Out','time']];foreach($fields as [$key,$label,$type]):?><div class="field"><label for="<?=rmmc_e($key)?>"><?=rmmc_e($label)?></label><input id="<?=rmmc_e($key)?>" name="<?=rmmc_e($key)?>" type="<?=rmmc_e($type)?>" value="<?=rmmc_e($event[$key]??'')?>" <?=in_array($key,['title','event_date','time_start','time_end','location'],true)?'required':''?>></div><?php endforeach; ?>
    <div class="field"><label for="organizer">Organizer</label><select id="organizer" name="organizer"><option value="ITE" <?=($event['organizer']??'ITE')==='ITE'?'selected':''?>>ITE Department</option><option value="COMSOC" <?=($event['organizer']??'')==='COMSOC'?'selected':''?>>COMSOC</option></select></div><div class="field"><label for="status">Event status</label><select id="status" name="status"><?php foreach($allowed as $v):?><option value="<?=rmmc_e($v)?>" <?=($event['status']??'Upcoming')===$v?'selected':''?>><?=rmmc_e($v)?></option><?php endforeach;?></select></div>
    <div class="field"><label for="required_join">Participants / description</label><input id="required_join" name="required_join" value="<?=rmmc_e($event['required_join']??'')?>" placeholder="e.g. BSIT 1st-4th Year"></div><div class="field"><label for="is_required">Attendance</label><select id="is_required" name="is_required"><option value="0" <?=empty($event['is_required'])?'selected':''?>>Optional</option><option value="1" <?=!empty($event['is_required'])?'selected':''?>>Required</option></select></div>
    <div class="field"><label for="applicable_courses">Applicable courses (comma separated; empty = all)</label><input id="applicable_courses" name="applicable_courses" value="<?=rmmc_e($event['applicable_courses']??'')?>" placeholder="BSIT,BSCS"></div><div class="field"><label for="applicable_years">Applicable year levels (comma separated; empty = all)</label><input id="applicable_years" name="applicable_years" value="<?=rmmc_e($event['applicable_years']??'')?>" placeholder="1st Year,2nd Year"></div>
    <div class="field span-2"><label for="description">Description</label><textarea id="description" name="description"><?=rmmc_e($event['description']??'')?></textarea></div></div><div class="row" style="margin-top:20px"><button><?=$edit?'Save changes':'Create event'?></button><?php if($edit):?><a class="btn ghost" href="events.php">Cancel editing</a><?php endif;?></div></form></section>
    <section class="panel"><div class="panel-header"><h2>All events</h2><form method="get" class="row"><select name="status" aria-label="Filter status"><option value="">All statuses</option><?php foreach($allowed as $v):?><option value="<?=$v?>" <?=$status===$v?'selected':''?>><?=$v?></option><?php endforeach;?></select><button>Filter</button></form></div><div class="table-scroll"><table class="data-table"><thead><tr><th>Event</th><th>Date</th><th>Organizer</th><th>Required</th><th>Status</th><th>Actions</th></tr></thead><tbody><?php foreach($rows as $ev):?><tr><td><?=rmmc_e($ev['title'])?></td><td><?=rmmc_e($ev['event_date'])?></td><td><?=rmmc_e($ev['organizer']??'ITE')?></td><td><?=!empty($ev['is_required'])?'Yes':'No'?></td><td><?=rmmc_badge($ev['status'])?></td><td><a href="?edit=<?=(int)$ev['id']?>">Edit</a> <?php if($ev['status']==='Finished' && !empty($ev['is_required'])):?>
    <form method="post" action="event_action.php" style="display:inline"><input type="hidden" name="csrf" value="<?=rmmc_e(rmmc_csrf())?>"><input type="hidden" name="action" value="finalize"><input type="hidden" name="id" value="<?=(int)$ev['id']?>"><button class="ghost" style="padding:6px 9px">Finalize fines</button></form>
    <?php endif; ?><?php if($ev['status']!=='Cancelled'):?><form method="post" action="event_action.php" style="display:inline" onsubmit="return confirm('Cancel this event? Attendance history will be kept.');"><input type="hidden" name="csrf" value="<?=rmmc_e(rmmc_csrf())?>"><input type="hidden" name="action" value="cancel"><input type="hidden" name="id" value="<?=(int)$ev['id']?>"><button class="ghost" style="padding:6px 9px">Cancel</button></form><?php endif;?></td></tr><?php endforeach;?></tbody></table></div><?php if(!$rows):?><p class="empty">No events found.</p><?php endif;?></section><?php rmmc_shell_end();
}
function rmmc_student_events(): void {
    rmmc_require_roles('Student');
    $rows=rmmc_all('SELECT * FROM events WHERE status <> ? ORDER BY event_date DESC LIMIT 100','s',['Cancelled']);
    rmmc_shell_start('Events','Student'); ?><div class="welcome"><h1>ITE and COMSOC events</h1><p>View event dates, organizers, attendance requirements, and sessions.</p></div><section class="panel"><div class="table-scroll"><table class="data-table"><tr><th>Event</th><th>Date</th><th>Time</th><th>Venue</th><th>Organizer</th><th>Attendance</th><th>Status</th></tr><?php foreach($rows as $ev):?><tr><td><strong><?=rmmc_e($ev['title'])?></strong><br><small><?=rmmc_e($ev['description'])?></small></td><td><?=rmmc_e($ev['event_date'])?></td><td><?=rmmc_e($ev['time_start'])?>–<?=rmmc_e($ev['time_end'])?></td><td><?=rmmc_e($ev['location'])?></td><td><?=rmmc_e($ev['organizer']??'ITE')?></td><td><?=!empty($ev['is_required'])?'Required':'Optional'?></td><td><?=rmmc_badge($ev['status'])?></td></tr><?php endforeach;?></table></div><?php if(!$rows):?><p class="empty">No events available.</p><?php endif;?></section><?php rmmc_shell_end();
}
